insert into catatan_surveyor (kos_id, hal_baik, perlu_diketahui, kesan_pemilik, red_flags) values
  ('525f7ba1-9ed1-49a5-a403-127764dc5252', array['Kamar mandi dalam berkeramik sampai plafon, dengan kloset duduk dan shower.', 'Ruang bersama di lantai atas berjendela besar dan bersofa; di ujung koridor ada kursi tunggu.', 'Rooftop terbuka dengan meja kayu dan area jemuran.']::text[], array['Tidak ada lift; kamar lantai 2 dan 3 lewat tangga.', 'Kamar sisi dalam berjendela ke koridor, bukan ke luar; bila butuh cahaya matahari, tanyakan kamar yang menghadap jalan.', 'Jalan depan kos dipakai parkir motor dan deretan galon, jadi menyempit saat ramai.']::text[], 'Sangat rapi, punya buku catatan kerusakan tiap kamar.', '{}'::text[]) on conflict (kos_id) do update set (hal_baik, perlu_diketahui, kesan_pemilik, red_flags) = (excluded.hal_baik, excluded.perlu_diketahui, excluded.kesan_pemilik, excluded.red_flags);
